// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;
    function setUp() public { c = new LiquidityPool(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address caller, address user) public {
        vm.assume(caller != user);
        uint256 callerWardBefore = c.wards(caller);
        vm.prank(caller);
        try c.rely(user) {} catch {}
        uint256 userWardAfter = c.wards(user);
        bool ok = (userWardAfter == 1) ? (callerWardBefore == 1) : true;
        assertTrue(ok);
    }
}
